// The plain Qwen3 host reference against tools/qwen3_reference.py on tiny
// synthetic checkpoints of every dialect and container
// (qwen3_reference_vectors.hpp, generated by tools/qwen3_synth.py vectors):
//
//   - the fixture written here from the ENGINE's binding table reaches the
//     content digest the tool computed from ITS OWN table and generator: the
//     same names, dtypes, shapes and bytes;
//   - the host forward in double (Arithmetic::Exact) reproduces the numpy
//     reference's float64 logits, teacher-forced log-probabilities, residual
//     stream and router decisions at rounding-noise tolerance — the numpy
//     side is itself held to transformers' Qwen3 classes by
//     `qwen3_synth.py torch-check`;
//   - the engine-rounding walk (Arithmetic::Engine) stays within bf16 noise
//     of it, and the routed-only NVFP4 MoE oracle within bf16 noise of the
//     exact block.
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <stdexcept>
#include <string>
#include <vector>

#include <unistd.h>

#include "common/dtypes.hpp"
#include "common/test.hpp"
#include "kernels/latent_format.hpp"
#include "models/qwen3/moe_reference.hpp"
#include "models/qwen3/reference.hpp"
#include "qwen3_fixture.hpp"
#include "qwen3_reference_vectors.hpp"

namespace {

namespace fs = std::filesystem;
namespace v = qwen3_reference_vectors;
using dgpp::qwen3_ref::Arithmetic;
using dgpp::qwen3_ref::HostCheckpoint;
using dgpp::qwen3_ref::Trace;

void require(bool cond, const std::string& what) {
  if (!cond) throw std::runtime_error(what);
}

// A scratch directory removed when the test leaves.
struct TempDir {
  fs::path path;
  explicit TempDir(const std::string& tag) {
    path = fs::temp_directory_path() / ("dgpp_qwen3_" + tag + "_" + std::to_string(static_cast<long>(::getpid())));
    fs::remove_all(path);
    fs::create_directories(path);
  }
  ~TempDir() {
    std::error_code ec;
    fs::remove_all(path, ec);
  }
};

std::vector<int64_t> ids() { return std::vector<int64_t>(v::kIds, v::kIds + v::kTokens); }

double max_abs_diff(const double* a, const double* b, size_t n) {
  double worst = 0;
  for (size_t i = 0; i < n; ++i) worst = std::max(worst, std::fabs(a[i] - b[i]));
  return worst;
}

// One preset's vectors, by reference.
struct Preset {
  const char* name;
  const char* config_json;
  bool bare_names;
  uint64_t digest;
  int tensors;
  uint64_t bytes;
  int vocab, layers, top_k;
  const double* state_sum;
  const double* state_abs_sum;
  const double* logits_last;
  const double* logits_first;
  const double* logprobs;
  const int32_t* router_ids;
};
#define QWEN3_PRESET(ns)                                                                              \
  Preset{#ns, v::ns::kConfigJson, v::ns::kBareNames, v::ns::kDigest, v::ns::kTensors, v::ns::kBytes, \
         v::ns::kVocab, v::ns::kLayers, v::ns::kTopK, v::ns::kStateSum, v::ns::kStateAbsSum,         \
         v::ns::kLogitsLast, v::ns::kLogitsFirst, v::ns::kLogprobs, v::ns::kRouterIds}

void check_exact(const Preset& p) {
  const TempDir dir(p.name);
  qwen3_fixture::write_checkpoint(dir.path.string(), p.config_json, p.bare_names, v::kSeed);
  const HostCheckpoint ck(dir.path.string());
  const std::string who = std::string(p.name) + ": ";
  // The engine's table and this generator against the tool's.
  require(ck.config().bare_names == p.bare_names, who + "the header's naming");
  require(ck.tensor_count() == static_cast<size_t>(p.tensors), who + "tensor count " + std::to_string(ck.tensor_count()));
  require(ck.report().ok() && ck.report().matched == static_cast<size_t>(p.tensors), who + "the whole header binds");
  require(ck.report().bytes == p.bytes, who + "tensor bytes");
  require(ck.content_digest() == p.digest, who + "content digest (names, dtypes, shapes and bytes equal the tool's)");

  Trace trace;
  const std::vector<int64_t> tok = ids();
  const std::vector<double> logits = dgpp::qwen3_ref::forward(ck, tok, Arithmetic::Exact, &trace);
  const size_t T = tok.size(), V = static_cast<size_t>(p.vocab);
  require(logits.size() == T * V, who + "logits shape");
  const double d_last = max_abs_diff(logits.data() + (T - 1) * V, p.logits_last, V);
  const double d_first = max_abs_diff(logits.data(), p.logits_first, V);
  require(d_last < 1e-9 && d_first < 1e-9,
          who + "logits vs numpy float64: max |d| " + std::to_string(std::max(d_last, d_first)));
  const std::vector<double> lp = dgpp::qwen3_ref::teacher_forced_logprobs(logits, tok, p.vocab);
  require(lp.size() == T - 1 && max_abs_diff(lp.data(), p.logprobs, T - 1) < 1e-9, who + "teacher-forced log-probabilities");
  // The residual stream after the embedding and every layer.
  require(trace.states.size() == static_cast<size_t>(p.layers) + 1, who + "one state per layer");
  for (size_t L = 0; L < trace.states.size(); ++L) {
    double sum = 0, abs_sum = 0;
    for (const double x : trace.states[L]) {
      sum += x;
      abs_sum += std::fabs(x);
    }
    require(std::fabs(sum - p.state_sum[L]) < 1e-8 * (1.0 + abs_sum) && std::fabs(abs_sum - p.state_abs_sum[L]) < 1e-9 * (1.0 + abs_sum),
            who + "residual stream after layer " + std::to_string(L));
  }
  // The router's decisions, every layer and token (ascending ids).
  if (p.top_k > 0) {
    require(trace.router_ids.size() == static_cast<size_t>(p.layers), who + "one route per layer");
    for (size_t L = 0; L < trace.router_ids.size(); ++L) {
      const std::vector<int32_t>& got = trace.router_ids[L];
      require(got.size() == T * static_cast<size_t>(p.top_k), who + "route shape");
      for (size_t i = 0; i < got.size(); ++i)
        require(got[i] == p.router_ids[L * T * static_cast<size_t>(p.top_k) + i], who + "selected experts, layer " + std::to_string(L));
    }
  } else {
    require(trace.router_ids.empty(), who + "no router in the dense dialect");
  }
}

}  // namespace

DGPP_TEST(qwen3_reference_vl_packed_equals_numpy) { check_exact(QWEN3_PRESET(vl)); }
DGPP_TEST(qwen3_reference_moe_modelopt_equals_numpy) { check_exact(QWEN3_PRESET(moe)); }
DGPP_TEST(qwen3_reference_dense_equals_numpy) { check_exact(QWEN3_PRESET(dense)); }
DGPP_TEST(qwen3_reference_dense_bare_names_equals_numpy) { check_exact(QWEN3_PRESET(dense_bare)); }

DGPP_TEST(qwen3_reference_engine_rounding_stays_within_bf16_noise) {
  for (const Preset& p : {QWEN3_PRESET(vl), QWEN3_PRESET(moe)}) {
    const TempDir dir(std::string(p.name) + "_engine");
    qwen3_fixture::write_checkpoint(dir.path.string(), p.config_json, p.bare_names, v::kSeed);
    const HostCheckpoint ck(dir.path.string());
    const std::vector<int64_t> tok = ids();
    Trace exact_trace, engine_trace;
    const std::vector<double> exact = dgpp::qwen3_ref::forward(ck, tok, Arithmetic::Exact, &exact_trace);
    const std::vector<double> engine = dgpp::qwen3_ref::forward(ck, tok, Arithmetic::Engine, &engine_trace);
    const std::vector<double> lp_exact = dgpp::qwen3_ref::teacher_forced_logprobs(exact, tok, p.vocab);
    const std::vector<double> lp_engine = dgpp::qwen3_ref::teacher_forced_logprobs(engine, tok, p.vocab);
    double worst = 0, mean = 0;
    for (size_t i = 0; i < lp_exact.size(); ++i) {
      worst = std::max(worst, std::fabs(lp_exact[i] - lp_engine[i]));
      mean += std::fabs(lp_exact[i] - lp_engine[i]) / static_cast<double>(lp_exact.size());
    }
    // bf16 activations and bf16 dense weights over three layers: a few
    // hundredths of a nat at the worst position, never a different shape.
    require(worst < 0.08 && mean < 0.03, std::string(p.name) + ": engine-rounding log-probabilities drift " +
                                             std::to_string(worst) + " max / " + std::to_string(mean) + " mean nat");
    // The final hidden state, relative to its scale.
    double num = 0, den = 0;
    for (size_t i = 0; i < exact_trace.final_hidden.size(); ++i) {
      const double d = exact_trace.final_hidden[i] - engine_trace.final_hidden[i];
      num += d * d;
      den += exact_trace.final_hidden[i] * exact_trace.final_hidden[i];
    }
    require(std::sqrt(num / den) < 0.02, std::string(p.name) + ": final hidden rel l2 " + std::to_string(std::sqrt(num / den)));
    // The first layer routes from the same normed input up to bf16 rounding:
    // the engine's router picks the same experts unless two logits tie to bf16.
    size_t same = 0;
    for (size_t i = 0; i < exact_trace.router_ids[0].size(); ++i) same += exact_trace.router_ids[0][i] == engine_trace.router_ids[0][i];
    require(same * 10 >= exact_trace.router_ids[0].size() * 9, std::string(p.name) + ": layer-0 routes agree on " +
                                                                    std::to_string(same) + " of " + std::to_string(exact_trace.router_ids[0].size()));
  }
}

DGPP_TEST(qwen3_reference_refuses_what_the_text_path_does_not_serve) {
  const TempDir dir("refusals");
  const dgpp::Qwen3TextConfig cfg = qwen3_fixture::write_checkpoint(dir.path.string(), v::vl::kConfigJson, false, v::kSeed);
  const HostCheckpoint ck(dir.path.string());
  const auto throws = [&](std::vector<int64_t> tok, Arithmetic a, const std::string& needle) {
    try {
      (void)dgpp::qwen3_ref::forward(ck, tok, a);
    } catch (const std::invalid_argument& e) {
      return std::string(e.what()).find(needle) != std::string::npos;
    }
    return false;
  };
  require(throws({1, cfg.image_token_id, 3}, Arithmetic::Exact, "vision tower is not served"), "an image placeholder is refused by name");
  require(throws({1, cfg.video_token_id, 3}, Arithmetic::Engine, "vision tower is not served"), "a video placeholder is refused by name");
  require(throws({1, cfg.vocab_size, 3}, Arithmetic::Exact, "out of range"), "a token id past the vocabulary");
  require(throws({}, Arithmetic::Exact, "empty"), "an empty prompt");
  // The dense dialect has no engine walk.
  const TempDir ddir("dense_engine");
  qwen3_fixture::write_checkpoint(ddir.path.string(), v::dense::kConfigJson, false, v::kSeed);
  const HostCheckpoint dck(ddir.path.string());
  bool threw = false;
  try {
    (void)dgpp::qwen3_ref::forward(dck, ids(), Arithmetic::Engine);
  } catch (const std::invalid_argument&) {
    threw = true;
  }
  require(threw, "the dense dialect's Engine arithmetic is refused");
  // The check apps' --layers: a truncated config binds, the layers past it out of scope.
  {
    const TempDir mdir("truncated");
    qwen3_fixture::write_checkpoint(mdir.path.string(), v::moe::kConfigJson, false, v::kSeed);
    const HostCheckpoint truncated(mdir.path.string(), /*layers=*/2);
    require(truncated.config().num_hidden_layers == 2 && truncated.report().ok() && truncated.report().out_of_scope > 0,
            "--layers truncation binds");
    Trace trace;
    (void)dgpp::qwen3_ref::forward(truncated, ids(), Arithmetic::Exact, &trace);
    require(trace.states.size() == 3, "two layers walked");
  }
  // A directory without a checkpoint does not open.
  {
    const TempDir empty("empty");
    bool refused = false;
    try {
      const HostCheckpoint none(empty.path.string());
    } catch (const std::runtime_error&) {
      refused = true;
    }
    require(refused, "no config.json");
  }
}

DGPP_TEST(qwen3_fp4_dequant_follows_each_containers_scale_direction) {
  // One row of 32 codes: every code value, under two block scales.
  uint8_t payload[16], scales[2] = {0x38, 0x41};  // e4m3 1.0 and 2.25
  for (int j = 0; j < 16; ++j) payload[j] = static_cast<uint8_t>((j & 0xF) | (((15 - j) & 0xF) << 4));
  float f[32];
  uint16_t b[32];
  const float mag[8] = {0.0f, 0.5f, 1.0f, 1.5f, 2.0f, 3.0f, 4.0f, 6.0f};
  const auto code = [&](int c) {
    const int nib = (c & 1) ? ((15 - c / 2) & 0xF) : ((c / 2) & 0xF);
    return (nib & 8) ? -mag[nib & 7] : mag[nib & 7];
  };
  require(dgpp::fp8_e4m3_bits_to_float(0x38) == 1.0f && dgpp::fp8_e4m3_bits_to_float(0x41) == 2.25f, "the two block scales");
  // modelopt: the global multiplies.
  dgpp::qwen3_ref::fp4_dequant_f32(payload, 16, scales, 2, 0.01171875f, /*global_divides=*/false, 1, 32, f);
  dgpp::qwen3_ref::fp4_dequant_bf16(payload, 16, scales, 2, 0.01171875f, false, 1, 32, b);
  for (int c = 0; c < 32; ++c) {
    const float s = (c < 16 ? 1.0f : 2.25f) * 0.01171875f;
    require(f[c] == code(c) * s, "modelopt fp32 value, column " + std::to_string(c));
    require(b[c] == dgpp::float_to_bf16_bits(code(c) * (c < 16 ? 1.0f : 2.25f) * 0.01171875f), "modelopt bf16 value");
  }
  // compressed-tensors: the global divides the block scale first.
  dgpp::qwen3_ref::fp4_dequant_f32(payload, 16, scales, 2, 96.0f, /*global_divides=*/true, 1, 32, f);
  dgpp::qwen3_ref::fp4_dequant_bf16(payload, 16, scales, 2, 96.0f, true, 1, 32, b);
  for (int c = 0; c < 32; ++c) {
    const float s = (c < 16 ? 1.0f : 2.25f) / 96.0f;
    require(f[c] == code(c) * s, "compressed-tensors fp32 value, column " + std::to_string(c));
    require(b[c] == dgpp::float_to_bf16_bits(code(c) * s), "compressed-tensors bf16 value");
  }
  // The low nibble is the even column.
  require(f[0] == 0.0f && f[1] == -6.0f * (1.0f / 96.0f), "nibble order");
}

DGPP_TEST(qwen3_moe_oracle_is_the_exact_block_within_bf16) {
  // One layer of the synthetic modelopt checkpoint, its own normed inputs.
  const TempDir dir("moe_oracle");
  qwen3_fixture::write_checkpoint(dir.path.string(), v::moe::kConfigJson, false, v::kSeed);
  const HostCheckpoint ck(dir.path.string());
  const dgpp::Qwen3TextConfig& c = ck.config();
  const dgpp::Qwen3MoeHostWeights w = ck.experts(1);
  require(w.hidden == c.hidden_size && w.inter == c.moe_intermediate_size && w.n_experts == c.num_experts, "geometry");
  // modelopt's multiplier is stored as the kernels' divisor.
  {
    float ws2;
    std::memcpy(&ws2, ck.tensor("model.layers.1.mlp.experts.3.down_proj.weight_scale_2").data, 4);
    require(w.globals[3 * 3 + 2] == 1.0f / ws2, "divisor = 1 / weight_scale_2");
  }
  const int T = 5, H = c.hidden_size;
  std::vector<uint16_t> x(static_cast<size_t>(T) * H);
  for (size_t i = 0; i < x.size(); ++i)
    x[i] = dgpp::float_to_bf16_bits(static_cast<float>(static_cast<int>((i * 37 + 11) % 61) - 30) / 24.0f);
  std::vector<uint16_t> out;
  dgpp::GlmMoeRouterRef route;
  dgpp::qwen3_moe_ref_forward(x.data(), w, c.moe_config(c.moe_intermediate_size), T, out, &route);
  require(out.size() == x.size() && route.ids.size() == static_cast<size_t>(T) * c.num_experts_per_tok, "shapes");
  for (int t = 0; t < T; ++t) {
    double wsum = 0;
    for (int i = 0; i < c.num_experts_per_tok; ++i) {
      const size_t at = static_cast<size_t>(t) * c.num_experts_per_tok + i;
      require(i == 0 || route.ids[at] > route.ids[at - 1], "ids ascending and distinct");
      wsum += route.weights[at];
    }
    require(std::fabs(wsum - 1.0) < 0.02, "top-k weights renormalized (bf16 each)");
  }
  // The exact block on the same inputs: router softmax -> top-k -> renorm,
  // dequantized experts in double. The oracle differs by its bf16 points.
  double num = 0, den = 0;
  for (int t = 0; t < T; ++t) {
    std::vector<double> acc(static_cast<size_t>(H), 0.0);
    for (int i = 0; i < c.num_experts_per_tok; ++i) {
      const size_t at = static_cast<size_t>(t) * c.num_experts_per_tok + i;
      const int e = route.ids[at];
      const std::string base = "model.layers.1.mlp.experts." + std::to_string(e) + ".";
      int64_t I = 0, K = 0;
      const std::vector<float> wg = ck.linear(base + "gate_proj", &I, &K), wu = ck.linear(base + "up_proj"), wd = ck.linear(base + "down_proj");
      std::vector<double> act(static_cast<size_t>(I));
      for (int64_t r = 0; r < I; ++r) {
        double g = 0, u = 0;
        for (int k = 0; k < H; ++k) {
          const double xv = dgpp::bf16_bits_to_float(x[static_cast<size_t>(t) * H + k]);
          g += xv * wg[static_cast<size_t>(r) * H + k];
          u += xv * wu[static_cast<size_t>(r) * H + k];
        }
        act[static_cast<size_t>(r)] = g / (1.0 + std::exp(-g)) * u;
      }
      for (int d = 0; d < H; ++d) {
        double y = 0;
        for (int64_t r = 0; r < I; ++r) y += act[static_cast<size_t>(r)] * wd[static_cast<size_t>(d) * I + r];
        acc[static_cast<size_t>(d)] += static_cast<double>(route.weights[at]) * y;
      }
    }
    for (int d = 0; d < H; ++d) {
      const double got = dgpp::bf16_bits_to_float(out[static_cast<size_t>(t) * H + d]);
      num += (got - acc[static_cast<size_t>(d)]) * (got - acc[static_cast<size_t>(d)]);
      den += acc[static_cast<size_t>(d)] * acc[static_cast<size_t>(d)];
    }
  }
  require(den > 0 && std::sqrt(num / den) < 0.02, "oracle vs the exact block: rel l2 " + std::to_string(std::sqrt(num / den)));
}
